import { atom } from '../../vanilla.js'
import type { WritableAtom } from '../../vanilla.js'
import { RESET } from './constants.js'

type Read<Value, Args extends unknown[], Result> = WritableAtom<
  Value,
  Args,
  Result
>['read']

type DefaultSetStateAction<Value> =
  Value | typeof RESET | ((prev: Value) => Value | typeof RESET)

/**
 * @guarantee ok.read-default The default value comes from the read function, so `atomWithDefault((get) => get(count1Atom) * 2)` with `count1Atom` equal to 1 has the value 2.
 * @guarantee ok.overwritten-detaches After the value is overwritten with `set`, the read function is no longer used and a change in dependency atoms does not update the value.
 * @guarantee ok.reset-restores Setting the atom to `RESET` discards changes made with `set` and restores the value computed by the read function.
 */
export function atomWithDefault<Value>(
  getDefault: Read<Value, [DefaultSetStateAction<Value>], void>,
): WritableAtom<Value, [DefaultSetStateAction<Value>], void> {
  const EMPTY = Symbol()
  const overwrittenAtom = atom<Value | typeof EMPTY>(EMPTY)

  if (process.env.NODE_ENV !== 'production') {
    overwrittenAtom.debugPrivate = true
  }

  const anAtom: WritableAtom<Value, [DefaultSetStateAction<Value>], void> =
    atom(
      (get, options) => {
        const overwritten = get(overwrittenAtom)
        if (overwritten !== EMPTY) {
          return overwritten
        }
        return getDefault(get, options)
      },
      (get, set, update) => {
        const newValue =
          typeof update === 'function'
            ? (update as (prev: Value) => Value)(get(anAtom))
            : update
        set(overwrittenAtom, newValue === RESET ? EMPTY : newValue)
      },
    )
  return anAtom
}

